CREATE TABLE evidence_items (
    id uuid NOT NULL DEFAULT uuidv7(),
    kind evidence_kind NOT NULL,
    recall_id uuid,
    certification_check_id uuid,
    source_record_id uuid,
    media_asset_id uuid,
    review_id uuid,
