    CONSTRAINT evidence_items_chk1 CHECK (bbox IS NULL OR (kind = 'media_region' AND cardinality(bbox) = 4)),
    CONSTRAINT evidence_items_chk2 CHECK (CASE kind WHEN 'recall' THEN recall_id IS NOT NULL AND num_nonnulls(certification_check_id, media_asset_id, review_id, hazard_flag_id) = 0 WHEN 'certification_check' THEN certification_check_id IS NOT NULL AND num_nonnulls(recall_id, media_asset_id, review_id, hazard_flag_id) = 0 WHEN 'source_record' THEN source_record_id IS NOT NULL AND num_nonnulls(recall_id, certification_check_id, media_asset_id, review_id, hazard_flag_id) = 0 WHEN 'media_region' THEN media_asset_id IS NOT NULL AND num_nonnulls(recall_id, certification_check_id, source_record_id, review_id, hazard_flag_id) = 0 WHEN 'review' THEN review_id IS NOT NULL AND num_nonnulls(recall_id, certification_check_id, source_record_id, media_asset_id, hazard_flag_id) = 0 WHEN 'hazard_flag' THEN hazard_flag_id IS NOT NULL AND num_nonnulls(recall_id, certification_check_id, source_record_id, media_asset_id, review_id) = 0 WHEN 'web_document' THEN url IS NOT NULL AND num_nonnulls(recall_id, certification_check_id, source_record_id, media_asset_id, review_id, hazard_flag_id) = 0 END)
);
