    status recall_status NOT NULL DEFAULT 'active',
    url text,
    source_record_id uuid,
    search_tsv tsvector GENERATED ALWAYS AS (to_tsvector('english'::regconfig, coalesce(title,'') || ' ' || coalesce(description,'') || ' ' || coalesce(hazard,''))) STORED,
    synced_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT recalls_pkey PRIMARY KEY (id),
    CONSTRAINT recalls_data_source_code_external_id_key UNIQUE (data_source_code, external_id)
);
COMMENT ON TABLE recalls IS 'Official recall notices (CPSC, openFDA; later NHTSA, EU Safety Gate…). Reference data.';
