-- ── screenings (Screening, Hazard & Passport) ──
CREATE TABLE screenings (
    id uuid NOT NULL DEFAULT uuidv7(),
    product_id uuid NOT NULL,
    run_type screening_run_type NOT NULL,
    status run_status NOT NULL DEFAULT 'running',
    verdict recall_verdict,
    rationale text,
    candidates_considered smallint,
    corpus_synced_at timestamptz NOT NULL,
    model_code text,
    prompt_version text,
    started_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    CONSTRAINT screenings_pkey PRIMARY KEY (id),
    CONSTRAINT screenings_id_product_id_key UNIQUE (id, product_id),
    CONSTRAINT screenings_chk1 CHECK ((status = 'completed') = (verdict IS NOT NULL)),
    CONSTRAINT screenings_chk2 CHECK ((status = 'running') = (completed_at IS NULL))
);
COMMENT ON TABLE screenings IS 'One recall-screening run for a product, as of a corpus snapshot. Only the completion fields may change, once.';
COMMENT ON COLUMN screenings.corpus_synced_at IS '''no match'' is only true as of this time';

-- ── screening_matches (Screening, Hazard & Passport) ──
CREATE TABLE screening_matches (
    screening_id uuid NOT NULL,
    recall_id uuid NOT NULL,
    rank smallint NOT NULL,
    retrieval_score real,
    verdict candidate_verdict NOT NULL,
    confidence numeric(4,3),
    rationale text,
    CONSTRAINT screening_matches_pkey PRIMARY KEY (screening_id, recall_id)
);
COMMENT ON TABLE screening_matches IS 'Candidate recalls retrieved for a screening and the model''s per-candidate verdict.';

-- ── passports (Screening, Hazard & Passport) ──
CREATE TABLE passports (
    id uuid NOT NULL DEFAULT uuidv7(),
    product_id uuid NOT NULL,
    version integer NOT NULL,
    tier smallint NOT NULL,
    status_badge passport_badge NOT NULL,
    trust_score numeric(5,2),
    recall_component numeric(5,2),
    certification_component numeric(5,2),
    hazard_component numeric(5,2),
    screening_id uuid,
    hazard_assessment_id uuid,
    formula_version text NOT NULL,
    verified_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT passports_pkey PRIMARY KEY (id),
    CONSTRAINT passports_product_id_version_key UNIQUE (product_id, version),
    CONSTRAINT passports_id_product_id_key UNIQUE (id, product_id),
    CONSTRAINT passports_chk1 CHECK (version > 0),
    CONSTRAINT passports_chk2 CHECK (tier BETWEEN 0 AND 2),
    CONSTRAINT passports_chk3 CHECK (trust_score BETWEEN 0 AND 100),
    CONSTRAINT passports_chk4 CHECK (tier = 2 OR status_badge = 'needs_information'),
    CONSTRAINT passports_chk5 CHECK (tier < 2 OR (screening_id IS NOT NULL AND trust_score IS NOT NULL))
);
COMMENT ON TABLE passports IS 'Versioned Product Passport. A new version on every verdict change. Composite FKs guarantee it cites THIS product''s screening/assessment.';
COMMENT ON COLUMN passports.tier IS '0 unidentified · 1 identified · 2 verified';

-- ── passport_evidence (Screening, Hazard & Passport) ──
CREATE TABLE passport_evidence (
    passport_id uuid NOT NULL,
    evidence_id uuid NOT NULL,
    purpose evidence_purpose NOT NULL,
    CONSTRAINT passport_evidence_pkey PRIMARY KEY (passport_id, evidence_id)
);
COMMENT ON TABLE passport_evidence IS 'Evidence shown on a passport version, grouped by purpose.';

-- ── wallet_items (Digital Wallet) ──
CREATE TABLE wallet_items (
    id uuid NOT NULL DEFAULT uuidv7(),
    user_id uuid NOT NULL,
    product_id uuid NOT NULL,
    add_method wallet_add_method NOT NULL,
    identification_request_id uuid,
    status wallet_item_status NOT NULL,
    verified_by_verification_id uuid,
    nickname text,
    notes text,
    alerts_enabled boolean NOT NULL DEFAULT true,
    last_seen_passport_id uuid,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    deleted_at timestamptz,
    CONSTRAINT wallet_items_pkey PRIMARY KEY (id),
    CONSTRAINT wallet_items_chk1 CHECK (add_method NOT IN ('manual','barcode') OR status <> 'active' OR verified_by_verification_id IS NOT NULL)
);
COMMENT ON TABLE wallet_items IS 'A product in a user''s Digital Wallet. Manual/barcode adds stay pending until a matching video verification exists.';
COMMENT ON COLUMN wallet_items.status IS 'no default: app chooses by add_method';
COMMENT ON COLUMN wallet_items.deleted_at IS 'soft delete';

-- ── wallet_item_verifications (Digital Wallet) ──
CREATE TABLE wallet_item_verifications (
    id uuid NOT NULL DEFAULT uuidv7(),
    wallet_item_id uuid NOT NULL,
    media_asset_id uuid NOT NULL,
    result video_check_result NOT NULL DEFAULT 'pending',
    confidence numeric(4,3),
    mismatch_reason text,
    model_code text,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT wallet_item_verifications_pkey PRIMARY KEY (id),
    CONSTRAINT wallet_item_verifications_id_wallet_item_id_key UNIQUE (id, wallet_item_id),
    CONSTRAINT wallet_item_verifications_chk1 CHECK (result <> 'mismatch' OR mismatch_reason IS NOT NULL)
);
COMMENT ON TABLE wallet_item_verifications IS 'Short-video proof that the user has the manual/barcode-added product.';

-- ── wallet_labels (Digital Wallet) ──
CREATE TABLE wallet_labels (
    id uuid NOT NULL DEFAULT uuidv7(),
    user_id uuid NOT NULL,
    name text NOT NULL,
    color text,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT wallet_labels_pkey PRIMARY KEY (id),
    CONSTRAINT wallet_labels_chk1 CHECK (length(name) BETWEEN 1 AND 40)
);
COMMENT ON TABLE wallet_labels IS 'User-defined custom labels (''kitchen'', ''kids room'').';

-- ── wallet_item_labels (Digital Wallet) ──
CREATE TABLE wallet_item_labels (
    wallet_item_id uuid NOT NULL,
    label_id uuid NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT wallet_item_labels_pkey PRIMARY KEY (wallet_item_id, label_id)
);
COMMENT ON TABLE wallet_item_labels IS 'Many-to-many: wallet items ↔ labels (same owner enforced by trigger).';

-- ── reviews (Community & Reviews) ──
CREATE TABLE reviews (
    id uuid NOT NULL DEFAULT uuidv7(),
    product_id uuid NOT NULL,
    origin content_origin NOT NULL DEFAULT 'user',
    author_user_id uuid,
    data_source_code text,
    external_id text,
    source_record_id uuid,
    rating smallint NOT NULL,
    title text,
    body text NOT NULL,
    author_reward_level smallint,
    verified_owner boolean NOT NULL DEFAULT false,
    geohash text,
    helpful_count integer NOT NULL DEFAULT 0,
    status content_status NOT NULL DEFAULT 'published',
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    deleted_at timestamptz,
    CONSTRAINT reviews_pkey PRIMARY KEY (id),
    CONSTRAINT reviews_chk1 CHECK (rating BETWEEN 1 AND 5),
    CONSTRAINT reviews_chk2 CHECK ((origin = 'user') = (author_user_id IS NOT NULL)),
    CONSTRAINT reviews_chk3 CHECK ((origin = 'ingested') = (data_source_code IS NOT NULL AND external_id IS NOT NULL AND source_record_id IS NOT NULL)),
    CONSTRAINT reviews_chk4 CHECK (helpful_count >= 0),
    CONSTRAINT reviews_chk5 CHECK (geohash IS NULL OR geohash ~ '^[0-9b-hjkmnp-z]{6}$')
);
COMMENT ON TABLE reviews IS 'Product reviews by users, or ingested from marketplaces (keyed on source + external id so re-ingestion updates, not duplicates).';
COMMENT ON COLUMN reviews.source_record_id IS 'latest version';
COMMENT ON COLUMN reviews.author_reward_level IS 'snapshot at writing time';
COMMENT ON COLUMN reviews.geohash IS '~1 km cell, optional';
COMMENT ON COLUMN reviews.deleted_at IS 'soft delete';

-- ── review_media (Community & Reviews) ──
CREATE TABLE review_media (
    review_id uuid NOT NULL,
    media_asset_id uuid NOT NULL,
    sort_order smallint NOT NULL DEFAULT 0,
    CONSTRAINT review_media_pkey PRIMARY KEY (review_id, media_asset_id)
);
COMMENT ON TABLE review_media IS 'Photos attached to a review.';

-- ── review_votes (Community & Reviews) ──
CREATE TABLE review_votes (
    review_id uuid NOT NULL,
    user_id uuid NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT review_votes_pkey PRIMARY KEY (review_id, user_id)
);
COMMENT ON TABLE review_votes IS '''Helpful'' votes — one per user per review.';

-- ── app_settings (Platform, Audit & Operations) ──
CREATE TABLE app_settings (
    key text NOT NULL,
    value jsonb NOT NULL,
    description text,
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT app_settings_pkey PRIMARY KEY (key),
    CONSTRAINT app_settings_chk1 CHECK (key ~ '^[a-z0-9_]+(\.[a-z0-9_]+)+$')
);
COMMENT ON TABLE app_settings IS 'Typed runtime settings: quotas, caps, thresholds (wallet.max_items, identify.daily_quota, rewards.daily_cap, session timeouts…).';

-- ── audit_log (Platform, Audit & Operations) ──
CREATE TABLE audit_log (
    id uuid NOT NULL DEFAULT uuidv7(),
    actor_type actor_type NOT NULL,
    actor_user_id uuid,
    action text NOT NULL,
    entity_type text NOT NULL,
    entity_id uuid,
    request_id text,
    trace_id text,
    ip_address inet,
    changes jsonb,
    metadata jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT audit_log_pkey PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);
COMMENT ON TABLE audit_log IS 'Permanent audit of every significant write. Monthly partitions.';
COMMENT ON COLUMN audit_log.actor_user_id IS 'no FK — survives account anonymisation';

-- ── indexes ──
CREATE UNIQUE INDEX users_u1_uidx ON users (phone_e164) WHERE phone_verified_at IS NOT NULL;
