CREATE INDEX auth_events_i1_idx ON auth_events (user_id, created_at DESC);
CREATE INDEX auth_events_i2_idx ON auth_events (ip_address, created_at DESC);
CREATE INDEX auth_events_i3_idx ON auth_events (email_attempted, created_at DESC);
CREATE INDEX manufacturers_i1_idx ON manufacturers USING gin (normalized_name gin_trgm_ops);
CREATE INDEX brands_i1_idx ON brands USING gin (normalized_name gin_trgm_ops);
CREATE UNIQUE INDEX products_u1_uidx ON products (brand_id, model_number_normalized) WHERE model_number_normalized IS NOT NULL AND brand_id IS NOT NULL AND status <> 'merged';
CREATE INDEX products_i1_idx ON products USING gist (canonical_name gist_trgm_ops(siglen=64));
CREATE INDEX products_i2_idx ON products (model_number_normalized);
CREATE INDEX products_i3_idx ON products (category_id, status);
CREATE INDEX media_blobs_i1_idx ON media_blobs (phash_band0);
CREATE INDEX media_blobs_i2_idx ON media_blobs (phash_band1);
CREATE INDEX media_blobs_i3_idx ON media_blobs (phash_band2);
CREATE INDEX media_blobs_i4_idx ON media_blobs (phash_band3);
CREATE UNIQUE INDEX media_assets_u1_uidx ON media_assets (owner_user_id, blob_id) WHERE owner_user_id IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX media_assets_i1_idx ON media_assets (owner_user_id, created_at DESC);
CREATE INDEX identification_requests_i1_idx ON identification_requests (user_id, created_at DESC);
CREATE INDEX ingestion_jobs_i1_idx ON ingestion_jobs (data_source_code, created_at DESC);
CREATE INDEX source_records_i1_idx ON source_records (data_source_code, record_type, external_id, fetched_at DESC);
CREATE INDEX recalls_i1_idx ON recalls USING gin (search_tsv);
CREATE INDEX recalls_i2_idx ON recalls (recall_date DESC);
CREATE INDEX recall_regions_i1_idx ON recall_regions (country_code, subdivision_code);
CREATE INDEX recall_products_i1_idx ON recall_products USING gin (brand_name gin_trgm_ops);
CREATE INDEX recall_products_i2_idx ON recall_products USING gist (product_name gist_trgm_ops(siglen=64));
CREATE INDEX recall_product_identifiers_i1_idx ON recall_product_identifiers (identifier_type, value_normalized);
CREATE INDEX certification_checks_i1_idx ON certification_checks (product_certification_id, checked_at DESC);
CREATE INDEX screenings_i1_idx ON screenings (product_id, started_at DESC);
CREATE INDEX screening_matches_i1_idx ON screening_matches (recall_id);
CREATE INDEX passports_i1_idx ON passports (status_badge);
CREATE UNIQUE INDEX wallet_items_u1_uidx ON wallet_items (user_id, product_id) WHERE deleted_at IS NULL;
CREATE INDEX wallet_items_i1_idx ON wallet_items (user_id, created_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX wallet_items_i2_idx ON wallet_items (product_id) WHERE deleted_at IS NULL AND alerts_enabled;
CREATE UNIQUE INDEX wallet_labels_u1_uidx ON wallet_labels (user_id, lower(name));
CREATE UNIQUE INDEX reviews_u1_uidx ON reviews (data_source_code, external_id) WHERE origin = 'ingested';
CREATE INDEX reviews_i1_idx ON reviews (product_id, created_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX reviews_i2_idx ON reviews (author_user_id, created_at DESC);
CREATE INDEX reviews_i3_idx ON reviews (geohash text_pattern_ops) WHERE geohash IS NOT NULL;
CREATE INDEX audit_log_i1_idx ON audit_log (entity_type, entity_id, created_at DESC);
CREATE INDEX audit_log_i2_idx ON audit_log (actor_user_id, created_at DESC);

